import Foundation
import Compression

// MARK: - Connection Pool for Serialization Service

final class SerializationConnection {
    let id: UUID
    var isAvailable: Bool = true
    var totalBytesProcessed: UInt64 = 0
    private let maxPayloadSize: Int = 10_485_760 // 10MB

    init() {
        self.id = UUID()
    }

    func processPayload(_ data: Data) throws -> Data {
        totalBytesProcessed += UInt64(data.count)
        return data
    }
}

final class ConnectionPool {
    private var connections: [SerializationConnection] = []
    private let poolSize: Int
    private let lock = NSLock()

    init(size: Int = 4) {
        self.poolSize = size
        for _ in 0..<size {
            connections.append(SerializationConnection())
        }
    }

    func acquire() -> SerializationConnection? {
        lock.lock()
        defer { lock.unlock() }
        if let conn = connections.first(where: { $0.isAvailable }) {
            conn.isAvailable = false
            return conn
        }
        return nil
    }

    func release(_ conn: SerializationConnection) {
        lock.lock()
        defer { lock.unlock() }
        conn.isAvailable = true
    }
}

// MARK: - Decompression Configuration

struct DecompressionPolicy {
    let maxCompressedSize: Int
    let maxDecompressedSize: Int
    let maxCompressionRatio: Double

    static let standard = DecompressionPolicy(
        maxCompressedSize: 5_242_880,    // 5MB compressed input
        maxDecompressedSize: 52_428_800,  // 50MB decompressed output
        maxCompressionRatio: 10.0         // max 10:1 ratio
    )
}

// MARK: - Streaming Decompressor

final class StreamingDecompressor {
    private let policy: DecompressionPolicy
    private let bufferSize: Int = 65_536

    init(policy: DecompressionPolicy = .standard) {
        self.policy = policy
    }

    func decompress(_ compressedData: Data) throws -> Data {
        guard compressedData.count <= policy.maxCompressedSize else {
            throw DecompressionError.inputTooLarge(compressedData.count)
        }

        var decompressed = Data()
        let outputFilter = try OutputFilter(.decompress, using: .zlib) { (data: Data?) in
            if let data = data {
                decompressed.append(data)
            }
        }

        // Process in chunks to enable streaming validation
        var offset = 0
        while offset < compressedData.count {
            let chunkEnd = min(offset + bufferSize, compressedData.count)
            let chunk = compressedData[offset..<chunkEnd]
            try outputFilter.write(chunk)
            offset = chunkEnd

            // Enforce hard limit on decompressed size at every chunk boundary
            if decompressed.count > policy.maxDecompressedSize {
                throw DecompressionError.decompressionBomb
            }

            // Also enforce ratio against total compressed input size
            let currentRatio = Double(decompressed.count) / Double(max(compressedData.count, 1))
            if currentRatio > policy.maxCompressionRatio {
                throw DecompressionError.decompressionBomb
            }
        }

        try outputFilter.finalize()

        // Final validation after finalize flushes remaining bytes
        guard decompressed.count <= policy.maxDecompressedSize else {
            throw DecompressionError.outputTooLarge(decompressed.count)
        }

        let finalRatio = Double(decompressed.count) / Double(max(compressedData.count, 1))
        guard finalRatio <= policy.maxCompressionRatio else {
            throw DecompressionError.decompressionBomb
        }

        return decompressed
    }
}

// MARK: - Serialization Service

final class SerializationService {
    private let pool: ConnectionPool
    private let decompressor: StreamingDecompressor
    private let maxAggregateSize: Int

    init(poolSize: Int = 4, policy: DecompressionPolicy = .standard) {
        self.pool = ConnectionPool(size: poolSize)
        self.decompressor = StreamingDecompressor(policy: policy)
        self.maxAggregateSize = policy.maxDecompressedSize * 2 // 100MB aggregate cap
    }

    func deserialize(_ payload: Data, compressed: Bool = false) throws -> Data {
        guard let conn = pool.acquire() else {
            throw ServiceError.noAvailableConnection
        }
        defer { pool.release(conn) }

        let rawData: Data
        if compressed {
            rawData = try decompressor.decompress(payload)
        } else {
            guard payload.count <= 52_428_800 else {
                throw ServiceError.payloadTooLarge
            }
            rawData = payload
        }

        let processed = try conn.processPayload(rawData)
        return processed
    }

    func deserializeJSON(_ payload: Data, compressed: Bool = false) throws -> [String: Any] {
        let processed = try deserialize(payload, compressed: compressed)
        guard let result = try JSONSerialization.jsonObject(with: processed) as? [String: Any] else {
            throw ServiceError.invalidFormat
        }
        return result
    }
}

// MARK: - Nested Archive Handler

final class NestedArchiveHandler {
    private let service: SerializationService
    private let maxNestingDepth: Int = 3
    private let maxAggregateDecompressedSize: Int
    private let maxEntries: Int = 100

    init(service: SerializationService, maxAggregateSize: Int = 104_857_600) {
        self.service = service
        self.maxAggregateDecompressedSize = maxAggregateSize // 100MB total
    }

    /// Processes archives that may contain nested compressed entries
    /// Enforces aggregate size limit across ALL entries
    func processArchive(_ archiveData: Data) throws -> [[String: Any]] {
        let manifest = try service.deserializeJSON(archiveData, compressed: true)

        guard let entries = manifest["entries"] as? [[String: Any]] else {
            return [manifest]
        }

        guard entries.count <= maxEntries else {
            throw ServiceError.payloadTooLarge
        }

        var results: [[String: Any]] = []
        var aggregateSize: Int = 0

        for entry in entries {
            guard let encodedPayload = entry["payload"] as? String,
                  let entryData = Data(base64Encoded: encodedPayload) else {
                continue
            }

            let isCompressed = (entry["compressed"] as? Bool) ?? false
            let decoded = try service.deserialize(entryData, compressed: isCompressed)

            aggregateSize += decoded.count
            guard aggregateSize <= maxAggregateDecompressedSize else {
                throw DecompressionError.decompressionBomb
            }

            guard let jsonResult = try JSONSerialization.jsonObject(with: decoded) as? [String: Any] else {
                throw ServiceError.invalidFormat
            }
            results.append(jsonResult)
        }

        return results
    }
}

// MARK: - Errors

enum DecompressionError: Error {
    case inputTooLarge(Int)
    case outputTooLarge(Int)
    case decompressionBomb
    case invalidData
}

enum ServiceError: Error {
    case noAvailableConnection
    case invalidFormat
    case payloadTooLarge
}
